actions.script:
import java.math.BigDecimal
def txMap = [:] for (def row in rawEntries) { def txId = row.acctgTransId def tx = txMap[txId] if (!tx) { tx = [ acctgTransId: txId, transactionDate: row.transactionDate, txDescription: row.txDescription ?: '', txVoucherRef: row.txVoucherRef ?: '', txVoucherDate: row.txVoucherDate, invoiceId: row.invoiceId, paymentId: row.paymentId, journalSequenceNum: row.journalSequenceNum, entries: [] ] txMap[txId] = tx } def isDebit = (row.debitCreditFlag == 'D') def amt = row.amount != null ? (BigDecimal) row.amount : BigDecimal.ZERO tx.entries.add([ acctgTransEntrySeqId: row.acctgTransEntrySeqId, glAccountId: row.glAccountId, accountCode: row.accountCode ?: row.glAccountId, accountName: row.accountName ?: '', debitCreditFlag: row.debitCreditFlag, debitAmount: isDebit ? amt : BigDecimal.ZERO, creditAmount: !isDebit ? amt : BigDecimal.ZERO ]) }
def txList = new ArrayList(txMap.values()) totalTransactions = txList.size() totalEntries = rawEntries.size()
// Sequential numbering if missing in preview int seq = 1 for (def tx in txList) { if (!tx.journalSequenceNum) tx.journalSequenceNum = seq seq++ }
// Page distribution pages = [] int currentPageNum = startPageNumber int maxLines = linesPerPage != null && linesPerPage > 5 ? linesPerPage : 26 int currentLineCount = 0
BigDecimal runningDebit = BigDecimal.ZERO BigDecimal runningCredit = BigDecimal.ZERO
BigDecimal pageDebit = BigDecimal.ZERO BigDecimal pageCredit = BigDecimal.ZERO
def currentPageRows = [] BigDecimal carriedForwardDebit = BigDecimal.ZERO BigDecimal carriedForwardCredit = BigDecimal.ZERO
for (def tx in txList) { int txLines = 1 + tx.entries.size() // header line + entry lines if (currentLineCount + txLines > maxLines && !currentPageRows.isEmpty()) { // Close current page BigDecimal carryOverDebit = carriedForwardDebit.add(pageDebit) BigDecimal carryOverCredit = carriedForwardCredit.add(pageCredit)
pages.add([ pageNumber: currentPageNum, pageLabel: "${fiscalYear} / ${currentPageNum}", carriedForwardDebit: carriedForwardDebit, carriedForwardCredit: carriedForwardCredit, transactions: currentPageRows, pageDebit: pageDebit, pageCredit: pageCredit, carryOverDebit: carryOverDebit, carryOverCredit: carryOverCredit ])
currentPageNum++ carriedForwardDebit = carryOverDebit carriedForwardCredit = carryOverCredit currentPageRows = [] pageDebit = BigDecimal.ZERO pageCredit = BigDecimal.ZERO currentLineCount = 0 }
currentPageRows.add(tx) currentLineCount += txLines for (def entry in tx.entries) { pageDebit = pageDebit.add(entry.debitAmount) pageCredit = pageCredit.add(entry.creditAmount) runningDebit = runningDebit.add(entry.debitAmount) runningCredit = runningCredit.add(entry.creditAmount) } }
// Add last page if (!currentPageRows.isEmpty() || pages.isEmpty()) { BigDecimal carryOverDebit = carriedForwardDebit.add(pageDebit) BigDecimal carryOverCredit = carriedForwardCredit.add(pageCredit) pages.add([ pageNumber: currentPageNum, pageLabel: "${fiscalYear} / ${currentPageNum}", carriedForwardDebit: carriedForwardDebit, carriedForwardCredit: carriedForwardCredit, transactions: currentPageRows, pageDebit: pageDebit, pageCredit: pageCredit, carryOverDebit: carryOverDebit, carryOverCredit: carryOverCredit ]) }
totalDebit = runningDebit totalCredit = runningCredit endPageNumber = currentPageNum

for (def page in journalData.pages) {
    for (def tx in page.transactions) {
        def txId = tx.acctgTransId
        def existing = ec.entity.find('mantle.ledger.transaction.AcctgTrans')
                .condition('acctgTransId', txId).one()
        if (existing && !existing.journalSequenceNum) {
            long nextNum = ec.entity.sequencedIdPrimary(seqName, 1, 1)
            existing.journalSequenceNum = nextNum
            existing.fiscalYear = fiscalYear
            existing.update()
            if (firstSeq == null) firstSeq = (int) nextNum
            lastSeq = (int) nextNum
        } else if (existing) {
            if (firstSeq == null) firstSeq = (int) existing.journalSequenceNum
            lastSeq = (int) existing.journalSequenceNum
        }
    }
}
